// 当前预检与历史可证性配对；有旧责任但无完整历史来源时明确拒，不能用今天空账倒填过去。
#include "family_inheritance_reads.hpp"
#include "resident/domains/tasks/task_actor_pending_responsibilities.hpp"
#include "resident/domains/tasks/task_inheritance_history.hpp"
#include "resident/domains/estate/estate_private_dependencies.hpp"
#include <tuple>
namespace hanmo::resident { namespace {
// 读戳核四项身份，避免不同候选或恢复前的旧空集被当作本次免责证明。
bool identity(const WorldIdentity& a,const WorldIdentity& b){return std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)==std::tie(b.world_id,b.execution_epoch,b.revision,b.tick);}
// 本域阻断不改原责任和资产，精确来源保留给错误诊断而不伪造清偿事实。
Status current_clear(const CommonStore& c,const EconomicPrivateAccountSelection& s,const Outcome<EconomicPrivateAccountDependencies>& result){if(!result.ok)return {false,{},result.error};if(!identity(result.value.source_identity,c.state().identity)||result.value.actor_id!=s.actor_id)return common_failure("InheritanceResponsibilitySourceMismatch");if(!result.value.blockers.empty())return common_failure("InheritancePrivateResponsibilityPending",result.value.blockers.front().source_id);return common_success();}
}
FamilyReceivedDeathNoticeRead family_received_death_notice_read(const TaskDeliveredDeathNoticeRead& original){return [original](const StableId& observer,const StableId& binding)->Outcome<std::optional<FamilyReceivedDeathNotice>>{if(!original)return {false,{},common_failure("InheritanceDeathNoticeReadRequired").error};auto received=original(observer,binding);if(!received.ok)return {false,{},received.error};if(!received.value)return {true,std::nullopt,{}};const auto& n=*received.value;FamilyReceivedDeathNotice out;out.identity=n.identity;out.scenario_id=n.scenario_id;out.binding_fact_id=n.binding_fact_id;out.task_id=n.task_id;out.source_lot_id=n.source_lot_id;out.handoff_fact_id=n.handoff_fact_id;out.death_fact_id=n.death_fact_id;out.decedent_actor_id=n.decedent_actor_id;out.sender_actor_id=n.sender_actor_id;out.recipient_actor_id=n.recipient_actor_id;out.issued_tick=n.issued_tick;out.received_tick=n.received_tick;return {true,std::move(out),{}};};}
// 原Estate借口按值保活；调用者局部access离开栈后，闭包不能继续解引用旧指针。
InheritancePrivateClearanceRead family_inheritance_private_clearance_read(const EconomicPrivateHistoryContext& context,const TaskState& tasks,const TaskCatalog& catalog){const auto estate_access=context.estate_access?std::optional<EstateAccess>{*context.estate_access}:std::nullopt;return [base=context,estate_access,&tasks,&catalog](const StableId& actor,const StableId& wallet,const StableId& inventory,Integer tick,const StableId& fact)->Status{auto context=base;context.estate_access=estate_access?&*estate_access:nullptr;const auto& c=context.common;EconomicPrivateAccountSelection selected{actor,{wallet},{inventory}};const auto* person=c.actor(actor);if(!person||person->alive||person->wallet_id!=wallet||person->inventory_id!=inventory)return common_failure("InheritanceOriginalPrivateAccountsRequired",actor);
 if(fact.empty()){
  if(tick!=c.tick())return common_failure("InheritanceResponsibilitySourceMismatch");auto current=current_clear(c,selected,read_economic_private_account_dependencies(c,context.economy,context.economy_catalog,context.fiscal,context.occupation,context.relief,selected,context.employment,context.shops));if(!current.ok)return current;current=current_clear(c,selected,read_estate_private_account_dependencies(c,context.estate,context.estate_catalog,context.common_catalog,selected,context.estate_access));if(!current.ok)return current;
  auto pending=read_task_actor_pending_responsibilities(c,tasks,catalog,actor);if(!pending.ok)return {false,{},pending.error};if(!identity(pending.value.source_identity,c.state().identity)||pending.value.actor_id!=actor)return common_failure("InheritanceResponsibilitySourceMismatch");if(!pending.value.pending_source_ids.empty())return common_failure("InheritanceTaskResponsibilityPending",pending.value.pending_source_ids.front());current=validate_task_inheritance_history_provable_now(c,tasks,catalog,actor);if(!current.ok)return current;
  auto proof=preview_economic_private_account_historical_clearance(context,selected);if(!proof.ok)return {false,{},proof.error};if(!identity(proof.value.source_identity,c.state().identity)||proof.value.actor_id!=actor||proof.value.tick!=tick||!proof.value.before_fact_id.empty())return common_failure("InheritanceResponsibilitySourceMismatch");return common_success();
 }
 // 冷验仅调用真实settled头之前的历史合同，后来的责任变化不能替换过去证明。
 auto old=validate_task_inheritance_history_before_fact(c,tasks,catalog,actor,fact,tick);if(!old.ok)return old;auto proof=read_economic_private_account_historical_clearance(context,selected,tick,fact);if(!proof.ok)return {false,{},proof.error};return identity(proof.value.source_identity,c.state().identity)&&proof.value.actor_id==actor&&proof.value.before_fact_id==fact&&proof.value.tick==tick?common_success():common_failure("InheritanceResponsibilitySourceMismatch");};}
}
